static int build_path(char *out, size_t out_size, const char *dir, const char *file) { int n = snprintf(out, out_size, "%s/%s", dir, file); return (n < 0 || (size_t)n >= out_size) ? 1 : 0; }
static int read_file_exact(const char *path, uint8_t packet[S1C5_PACKET_SIZE]) { FILE *f = fopen(path, "rb"); int extra; if (!f) { perror(path); return 1; } if (fread(packet, 1, S1C5_PACKET_SIZE, f) != S1C5_PACKET_SIZE) { fprintf(stderr, "S1-C5 packet must be exactly %u bytes: %s\n", (unsigned)S1C5_PACKET_SIZE, path); fclose(f); return 1; } extra = fgetc(f); fclose(f); if (extra != EOF) { fprintf(stderr, "S1-C5 packet has trailing bytes: %s\n", path); return 1; } return 0; }
static size_t packetize(const uint8_t *sysex, size_t length, uint8_t *events, size_t capacity) { size_t input = 0, output = 0; while (input < length) { size_t remaining = length - input; size_t count = remaining > 3 ? 3 : remaining; uint8_t cin; if (output + S1C5_USB_MIDI_PACKET_SIZE > capacity) return 0; cin = remaining > 3 ? 0x04 : (remaining == 1 ? 0x05 : (remaining == 2 ? 0x06 : 0x07)); events[output] = cin; events[output + 1] = sysex[input]; events[output + 2] = count > 1 ? sysex[input + 1] : 0; events[output + 3] = count > 2 ? sysex[input + 2] : 0; input += count; output += S1C5_USB_MIDI_PACKET_SIZE; } return output; }
static int verify_packet(const char *dir, const struct packet_spec *spec, uint8_t packet[S1C5_PACKET_SIZE], uint8_t events[S1C5_USB_MIDI_BYTES]) { uint8_t digest[SMK37_SHA256_LENGTH]; char path[S1C5_MAX_PATH]; size_t event_len; if (build_path(path, sizeof(path), dir, spec->file) != 0 || read_file_exact(path, packet) != 0) return 1; if (memcmp(packet, EXPECTED_HEADER, sizeof(EXPECTED_HEADER)) != 0 || packet[S1C5_PACKET_SIZE - 1] != 0xf7 || packet[161] != (uint8_t)spec->playback_note) { fprintf(stderr, "S1-C5 order %u slot %u trigger %u playback %u framing/playback mismatch\n", spec->order, spec->slot, spec->trigger_note, spec->playback_note); return 1; } smk37_sha256(packet, S1C5_PACKET_SIZE, digest); if (memcmp(digest, spec->sha256, sizeof(digest)) != 0) { fprintf(stderr, "S1-C5 order %u packet SHA-256 mismatch\n", spec->order); return 1; } event_len = packetize(packet, S1C5_PACKET_SIZE, events, S1C5_USB_MIDI_BYTES); if (event_len != S1C5_USB_MIDI_BYTES || events[event_len - 4] != 0x05 || events[event_len - 3] != 0xf7) { fputs("USB-MIDI packetization invariant failed\n", stderr); return 1; } return 0; }
