static void usage(const char *p) { fprintf(stderr, "usage:\n  %s dry-run <packet-dir>\n  %s send <packet-dir> --confirm %s\n", p, p, CONFIRM_TOKEN); }
int main(int argc, char **argv) { uint8_t packets[S1C5_PACKET_COUNT][S1C5_PACKET_SIZE]; uint8_t events[S1C5_PACKET_COUNT][S1C5_USB_MIDI_BYTES]; if (argc != 3 && argc != 5) { usage(argv[0]); return 2; } for (unsigned i = 0; i < S1C5_PACKET_COUNT; ++i) if (verify_packet(argv[2], &PACKETS[i], packets[i], events[i]) != 0) return 2; if (strcmp(argv[1], "dry-run") == 0 && argc == 3) { puts("S1-C5 Marked 16-packet sender dry-run PASS: triggers 36..51 all map to Playback Note C4 (60), 16 exact packets, no USB/MIDI opened"); return 0; } if (strcmp(argv[1], "send") == 0 && argc == 5 && strcmp(argv[3], "--confirm") == 0 && strcmp(argv[4], CONFIRM_TOKEN) == 0) return send_verified(events); usage(argv[0]); return 2; }
